values.content:
=Classify this email into exactly one category. Reply with ONLY the category word.

Categories:
URGENT - a customer or partner needs action today: outage, complaint, deadline, payment failure
CUSTOMER - normal customer or prospect communication
INVOICE - bills, receipts, payment confirmations
NEWSLETTER - marketing, digests, notifications, anything automated

From: {{ $json.from }}
Subject: {{ $json.subject }}

{{ ($json.textPlain || $json.snippet || '').slice(0, 2000) }}

parameters.jsCode:
const category = $input.first().json.message.content.trim().toUpperCase().replace(/[^A-Z]/g, '');
const labelMap = {
  URGENT: 'REPLACE_WITH_URGENT_LABEL_ID',
  CUSTOMER: 'REPLACE_WITH_CUSTOMER_LABEL_ID',
  INVOICE: 'REPLACE_WITH_INVOICE_LABEL_ID',
  NEWSLETTER: 'REPLACE_WITH_NEWSLETTER_LABEL_ID'
};
const src = $('New Email').first().json;
return [{ json: {
  messageId: src.id,
  category,
  labelId: labelMap[category] || labelMap.CUSTOMER,
  from: src.from, subject: src.subject
} }];
